const $=s=>document.querySelector(s), money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
const classes={'Disponível':'available','Reservado':'reserved','Vendido':'sold'},colors={'Disponível':'#bedda8','Reservado':'#e9c886','Vendido':'#a5b3bf'};
const initial=()=>Array.from({length:40},(_,i)=>{let floor=Math.floor(i/4)+1,end=i%4+1,front=end<=2,area=front?47:43;return {unidade:String(floor*100+end),andar:floor,posicao:front?'Frente':'Fundos',area,sacada:front,preco:200000+30000*(floor-1)+(front?30000:0),status:i%7===0?'Vendido':i%6===0?'Reservado':'Disponível'};});
let units=initial(),selected='701',view='model',angle=-Math.PI/6,faces=[];
function matches(u){return ($('#statusFilter').value==='all'||u.status===$('#statusFilter').value)&&($('#typeFilter').value==='all'||(u.sacada?'front':'rear')===$('#typeFilter').value)}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function planSvg(front){let balcony=front?'<rect x="35" y="269" width="240" height="27" fill="#d5edc2" stroke="#365066" stroke-width="3"/><text x="155" y="287" text-anchor="middle">SACADA · 4 m²</text>':'';return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 310 320" role="img" aria-label="Planta conceitual de ${front?47:43} metros quadrados" font-family="Arial,sans-serif" font-size="10" fill="#365066"><rect width="310" height="320" fill="#f7f9fa"/><g fill="#eef2f4" stroke="#365066" stroke-width="4"><path d="M35 25H275V269H35Z"/><path d="M155 25V111M155 139V177M35 146H129M155 177H217M245 177H275M217 25V96M217 121V177" fill="none"/></g><g stroke="#7ea3b3" stroke-width="5"><path d="M60 25H118M173 25H198M35 177V235M275 192V238"/></g><g fill="#d8e2e7" stroke="#9caeb9"><rect x="49" y="44" width="66" height="65" rx="3"/><rect x="51" y="46" width="62" height="17" rx="2"/><rect x="168" y="42" width="32" height="58" rx="2"/><rect x="170" y="44" width="28" height="14"/><rect x="231" y="41" width="30" height="27"/><ellipse cx="247" cy="84" rx="9" ry="12"/><rect x="232" y="135" width="32" height="23"/><rect x="49" y="178" width="27" height="67" rx="3"/><rect x="104" y="213" width="32" height="22" rx="3"/><rect x="170" y="207" width="38" height="38" rx="15"/><rect x="251" y="195" width="16" height="62"/></g><text x="91" y="130" text-anchor="middle">QUARTO 1</text><text x="184" y="130" text-anchor="middle">QUARTO 2</text><text x="246" y="112" text-anchor="middle">BANHO</text><text x="246" y="171" text-anchor="middle">SERVIÇO</text><text x="108" y="195" text-anchor="middle">ESTAR</text><text x="212" y="195" text-anchor="middle">COZINHA / JANTAR</text><path d="M142 269h27" stroke="#f7f9fa" stroke-width="6"/><path d="M142 269v-22m0 0a22 22 0 0 1 22 22" fill="none" stroke="#365066"/>${balcony}<text x="155" y="313" text-anchor="middle">ESQUEMA ILUSTRATIVO · SEM ESCALA</text></svg>`}
function render(){const counts=Object.fromEntries(Object.keys(classes).map(s=>[s,units.filter(u=>u.status===s).length]));$('#stats').innerHTML=`<div class="stat"><strong>${counts.Disponível}</strong><span>disponíveis</span></div><div class="stat"><strong>${counts.Reservado}</strong><span>reservados</span></div><div class="stat"><strong>${counts.Vendido}</strong><span>vendidos</span></div><div class="stat"><strong>${(counts.Vendido/40*100).toLocaleString('pt-BR')}%</strong><span>vendido</span></div>`;
$('#visibleCount').textContent=`${units.filter(matches).length} de 40`;
$('#unitGrid').innerHTML=Array.from({length:10},(_,i)=>10-i).map(f=>`<div class="floorrow"><span>${f}º</span>${units.filter(u=>u.andar===f).map(u=>`<button class="unit ${classes[u.status]} ${u.unidade===selected?'selected':''} ${matches(u)?'':'dimmed'}" data-unit="${u.unidade}" aria-pressed="${u.unidade===selected}" aria-label="Apartamento ${u.unidade}, ${u.area} metros quadrados, ${u.status}" title="${u.status} · ${money(u.preco)}">${u.unidade}</button>`).join('')}</div>`).join('');
document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{selectUnit(b.dataset.unit);if(matchMedia('(max-width: 720px)').matches){$('.visual').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}});renderDetails();drawTower()}
let turnFrame=0;
function selectUnit(id){const u=units.find(u=>u.unidade===id);if(!u)return;selected=id;setModelView('model');render();cancelAnimationFrame(turnFrame);const end=Number(id)%100,target=({1:-25,2:25,3:-155,4:155})[end]*Math.PI/180,start=angle;let delta=Math.atan2(Math.sin(target-start),Math.cos(target-start)),t0=performance.now();function step(t){let k=Math.min(1,(t-t0)/750),e=k*k*(3-2*k);angle=start+delta*e;syncRotation();drawTower();if(k<1)turnFrame=requestAnimationFrame(step)}if(matchMedia('(prefers-reduced-motion: reduce)').matches){angle=target;syncRotation();drawTower()}else turnFrame=requestAnimationFrame(step)}
function syncRotation(){let degrees=((angle*180/Math.PI+180)%360+360)%360-180;$('#rotation').value=Math.round(degrees);let abs=Math.abs(degrees);$('#orientation').textContent=abs<65?'Frente · rua à frente':abs>115?'Fundos · rua atrás':'Lateral · rua ao lado';$('#tower').setAttribute('aria-label','Modelo 3D do Aurora. '+$('#orientation').textContent+'. Unidade '+selected+' selecionada.');}
function setModelView(next){view=next;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));$('#modelView').hidden=view!=='model';$('#renderView').hidden=view!=='render';drawTower()}
function renderDetails(){let u=units.find(u=>u.unidade===selected);$('#details').innerHTML=`<p class="eyebrow">UNIDADE SELECIONADA</p><h2>Apartamento ${u.unidade}</h2><span class="badge ${classes[u.status]}">${u.status}</span><p class="price">${money(u.preco)}</p><p class="subprice">${money(u.preco/u.area)}/m² · preço demonstrativo</p><div class="facts"><div><strong>${u.area} m²</strong><span>${u.sacada?'inclui sacada':'sem sacada'}</span></div><div><strong>${u.andar}º andar</strong><span>${u.posicao}</span></div><div><strong>2</strong><span>dormitórios</span></div></div><div class="plan">${planSvg(u.sacada)}</div><p class="caption">${u.sacada?'43 m² internos + 4 m² de sacada.':'43 m² internos, sem sacada.'} Distribuição conceitual; áreas não calculadas pelo desenho.</p><a href="planta-${u.area}.svg" download>Baixar planta ilustrativa</a><details><summary>Editar unidade de teste</summary><div class="editrow"><label>Preço (R$)<input id="priceEdit" type="number" min="1" max="100000000" step="1" value="${u.preco}"></label><label>Situação<select id="statusEdit">${Object.keys(classes).map(s=>`<option ${s===u.status?'selected':''}>${s}</option>`).join('')}</select></label></div><button id="saveUnit" class="primary">Aplicar nesta sessão</button></details><button id="financeButton" class="primary finance-trigger">Simular financiamento e entrada</button>`;
$('#saveUnit').onclick=()=>{let n=Number($('#priceEdit').value);if(!Number.isFinite(n)||n<=0||n>1e8)return toast('Informe um preço entre R$ 1 e R$ 100 milhões.');u.preco=Math.round(n);u.status=$('#statusEdit').value;render();toast('Unidade atualizada. Exporte os dados para guardar.');};
$('#financeButton').onclick=()=>window.openAuroraFinance(u);window.syncAuroraFinance?.(u);}
function drawTower(){if(view!=='model')return;syncRotation();if(window.aurora3D)window.aurora3D.update({units,selected,angle,matching:units.filter(matches).map(u=>u.unidade)});}
$('#rotation').oninput=e=>{cancelAnimationFrame(turnFrame);angle=Number(e.target.value)*Math.PI/180;drawTower()};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setModelView(b.dataset.view));
$('#statusFilter').onchange=render;$('#typeFilter').onchange=render;$('#dataButton').onclick=()=>$('#dataDialog').showModal();
const csvText=()=>['unidade;andar;posicao;area;sacada;preco;status',...units.map(u=>[u.unidade,u.andar,u.posicao,u.area,u.sacada?'sim':'nao',u.preco,u.status].join(';'))].join('\r\n');
function download(name,text,type){let url=URL.createObjectURL(new Blob(['\ufeff',text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#exportButton').onclick=()=>download('aurora-unidades.csv',csvText(),'text/csv;charset=utf-8');
function parseCSV(text){const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/);if(lines.shift()!=='unidade;andar;posicao;area;sacada;preco;status')throw Error('Cabeçalho inválido. Use o CSV exportado como modelo.');if(lines.length!==40)throw Error('A tabela deve ter exatamente 40 unidades.');let seen=new Set();return lines.map((line,i)=>{let a=line.split(';');if(a.length!==7)throw Error(`Linha ${i+2}: use 7 campos separados por ponto e vírgula.`);let [unidade,floor,posicao,area,balcony,price,status]=a,andar=Number(floor),end=Number(unidade)%100,front=end<=2;let u={unidade,andar,posicao,area:Number(area),sacada:balcony==='sim',preco:Number(price),status};if(!/^\d{3,4}$/.test(unidade)||!Number.isInteger(andar)||andar<1||andar>10||end<1||end>4||Number(unidade)!==andar*100+end||seen.has(unidade)||posicao!==(front?'Frente':'Fundos')||u.area!==(front?47:43)||balcony!==(front?'sim':'nao')||!Number.isFinite(u.preco)||u.preco<=0||u.preco>1e8||!Object.hasOwn(classes,status))throw Error(`Linha ${i+2}: dados incompatíveis com este edifício. Confira unidade, geometria, preço e situação.`);seen.add(unidade);return u}).sort((a,b)=>Number(a.unidade)-Number(b.unidade))}
$('#importFile').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw Error('Arquivo muito grande. Use apenas a tabela de 40 unidades.');let next=parseCSV(await file.text());units=next;render();$('#importMessage').textContent='40 unidades importadas com sucesso.';toast('Tabela substituída nesta sessão.')}catch(err){$('#importMessage').textContent=err.message}e.target.value=''};
$('#resetButton').onclick=()=>{if(confirm('Restaurar os 40 apartamentos fictícios? Exporte antes para guardar suas alterações.')){units=initial();render();$('#importMessage').textContent='Cenário fictício restaurado.'}};
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'list_aurora_units',description:'Listar os 40 apartamentos do cenário atual, com preço e disponibilidade.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({units:units.map(u=>({...u})),selected})},{name:'select_aurora_unit',description:'Selecionar um apartamento existente no painel e mostrar sua planta e preço; não altera dados de venda.',inputSchema:{type:'object',properties:{unit:{type:'string'}},required:['unit'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.unit!=='string'||!units.some(u=>u.unidade===input.unit))throw Error('Unidade inexistente.');selectUnit(input.unit);return {selected,unit:{...units.find(u=>u.unidade===selected)}}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}}
